import @vibe/compiler/runtime { db_new, db_merged_source }
import @vibe/parser { set_cfg_ambient_flags }
fn main allows Env + Exception + Console {
  let sources = [("main.vibe", "#cfg(alpha)\nfn main() -> Int { 11 }\n#cfg(beta)\nfn main() -> Int { 22 }\n")]
  set_cfg_ambient_flags(["alpha"])
  let (alpha, _, db) = db_merged_source(db = db_new(), _entry_path = "main.vibe", sources = sources)
  set_cfg_ambient_flags(["beta"])
  let (beta, _, _) = db_merged_source(db = db, _entry_path = "main.vibe", sources = sources)
  assert(alpha != beta)
  assert(String::contains(beta, needle = "22"))
  println("merge flags isolated")
}
